    and c.case_status in ('processing','closing','closed','archived')
    and c.case_status in ('processing','closing','closed','archived') and (c.owner_id=#{currentUserId} or c.main_lawyer_id=#{currentUserId} or find_in_set(#{currentUserId}, ifnull(c.assistant_lawyer_ids,'')))
    and c.case_status in ('closing','closed','archived')
    and (c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or c.customer_name like concat('%',#{keyword},'%') or c.main_lawyer_name like concat('%',#{keyword},'%'))
    and c.case_type=#{caseType}
    and c.case_stage=#{caseStage}
    and c.case_status=#{caseStatus}
    and c.risk_level=#{riskLevel}
    and c.urgency=#{urgency}
    and c.archive_status=#{archiveStatus}
    and c.customer_id=#{customerId}
    and c.contract_id=#{contractId}
    and c.main_lawyer_id=#{mainLawyerId}
    and find_in_set(#{assistantLawyerId}, ifnull(c.assistant_lawyer_ids,''))


