mapper.update:
update biz_case
case_status=#{caseStatus}, archive_status=#{archiveStatus}, current_node=#{currentNode}, update_by=#{updateBy}, update_time=sysdate()
where case_id=#{caseId} and del_flag='0' and case_status=#{expectedStatus}

mapper.select:
select n.*, c.case_no caseNo,c.case_name caseName,c.customer_name customerName,c.case_status caseStatus
from biz_case_node n left join biz_case c on c.case_id=n.case_id

    and n.del_flag='0' and c.del_flag='0'
    and n.case_id=#{caseId}
    and n.node_status=#{nodeStatus}
    and n.node_type=#{nodeType}
    and (c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%') or n.node_name like concat('%',#{keyword},'%'))


order by n.plan_date asc,n.node_id asc

select e.*, c.case_no caseNo,c.case_name caseName,c.customer_name customerName,c.case_status caseStatus
from biz_case_expense e left join biz_case c on c.case_id=e.case_id

    and e.del_flag='0' and c.del_flag='0'
    and e.case_id=#{caseId}
    and e.expense_type=#{expenseType}
    and e.pay_status=#{payStatus}
    and (e.expense_no like concat('%',#{keyword},'%') or c.case_no like concat('%',#{keyword},'%') or c.case_name like concat('%',#{keyword},'%'))


order by e.occur_date desc,e.expense_id desc

select l.*, c.case_no caseNo,c.case_name caseName from biz_case_status_log l left join biz_case c on c.case_id=l.case_id
and c.del_flag='0' and l.case_id=#{caseId}
order by l.create_time desc
